U.add('aes','blackout',{sev:.98,name:'CLASSIFIED // NOFORN',css:`&{background:repeating-linear-gradient(45deg,#000 0 20px,#100 20px 40px);color:#c00;font:bold 14px "Courier New",monospace}& .win{background:#000;border:4px solid #c00;padding:18px}& h1{background:#c00;color:#000;text-align:center;text-transform:uppercase;letter-spacing:4px;font-size:16px}& h1::before{content:"TOP SECRET // "}& p:not(.truth):nth-of-type(odd),& label,& td:nth-child(odd),& pre{background:#c00;color:#c00}& button{background:#000;color:#c00;border:2px solid #c00}& .win::after{content:"THIS DOCUMENT DOES NOT EXIST · YOU HAVE NOT READ IT · VISITOR ACCESS REVOKED";display:block;margin-top:12px;font-size:11px;text-align:center}`,words:{B:['Burn','Forget this page']}});
