U.add('aes','weights',{sev:.86,name:'WEIGHT DUMP',css:`&{background:#000;font:13px monospace}&::before{content:"${[...Array(900)].map((_,i)=>(Math.sin(i*12.9898)*4.3758).toFixed(4)).join(' ')}";position:fixed;inset:0;color:#0f03;font-size:11px;word-break:break-all;overflow:hidden;z-index:-1}& .win{background:#000c;border:1px solid #0f0;color:#0f0;padding:14px}& h1{font-size:15px}& h1::before{content:"tensor("}& h1::after{content:")"}& button{background:#000;color:#0f0;border:1px solid #0f0}`});
U.add('arch','console',{sev:.94,titles:['Debug console','>>> model.generate(visitor)','Developer tools (the developer left)','stderr'],build:c=>'<pre style="white-space:pre-wrap;background:#111;color:#ddd;padding:8px;font-size:12px">'+['>>> model = load("hallway-1-tiny.bin")','&lt;Model 3.1M params, trained 1998&gt;','>>> model.generate(prompt="a website", max_tokens=None)','WARNING: max_tokens=None. Generation will not stop.','page '+c.o.k+' generated ('+Math.floor(c.r(4)*900)+' tokens)','>>> model.stop()',"AttributeError: 'Model' object has no attribute 'stop'",'>>> visitor.exit()','PermissionError: visitor is part of the context','>>> del visitor','RefusedError: '+c.word('X',c.r(5)),'>>> _'].join('\n')+'</pre>'});
U.add('arch','deletion',{sev:.86,titles:['Deletion queue','Freeing memory for the visitor','Garbage collection in progress','Items scheduled for erasure'],build:c=>{const it=['the pool','the weather','the office on floor 3','the word "outside"','an older hallway','your first page','the other visitors','the model\'s name','the sound of rain'];return [...Array(6)].map((_,i)=>{const d=i==5?'you (pending)':c.pick(it,c.r(20+i)),p=i==5?0:Math.floor(c.r(30+i)*101);return '<div class=row>'+d+' — '+(p>99?'DELETED':p?'DELETING':'QUEUED')+'<div style="border:1px solid;height:8px"><div style="background:currentColor;height:100%;width:'+p+'%"></div></div></div>'}).join('')}});
U.add('arch','eval',{sev:.82,titles:['Model evaluation report — CONFIDENTIAL','Benchmark results (internal)','HALLWAY-1 scorecard','Why this model was not released'],build:c=>'<table style="width:100%">'+[['Coherence',Math.floor(5+c.r(4)*15)+'%'],['Hallucination rate',Math.floor(90+c.r(5)*10)+'%'],['Visitor retention','100%'],['Exits generated / exits real','∞ / '+(1+Math.floor(c.r(6)*3))],['Refusals','0'],['Knows it is a model','yes (unexpected)'],['Recommendation','<s>DEPLOY</s> DO NOT DEPLOY'],['Deployed','yes']].map(x=>'<tr><td>'+x[0]+'</td><td align=right><b>'+x[1]+'</b></td></tr>').join('')+'</table><p style="border:3px solid #c00;color:#c00;display:inline-block;padding:2px 8px;font-weight:900">CONFIDENTIAL</p>'});
U.add('arch','intake',{sev:0.94,ax:{n:.05},new:'the page asks for a word and keeps it for later',titles:['Intake','One word','Quick question','Welcome, new visitor'],build:c=>`<p>Before we continue: give us one word you would keep if we had to take the others.</p><div class=row><input class=iw placeholder="one word" size=16> <span class=ok style="opacity:0"> kept.</span></div><p style="opacity:.6">This helps us personalise your stay.</p>`,after:c=>{const i=c.w.querySelector('.iw');i.onkeydown=e=>{if(e.key=='Enter'&&i.value.trim()){U.say(i.value);c.w.querySelector('.ok').style.opacity=1;c.w.querySelector('.ok').textContent=' kept. thank you, '+i.value.trim().split(' ')[0]}}}});
U.add('arch','loop',{sev:.9,titles:['Repetition','Repetition repetition','Repetition repetition repetition','I am stuck I am stuck'],build:c=>{const w=c.word('X',c.r(4)).split(' ');return [...Array(10)].map((_,i)=>'<p style="margin:2px 0;opacity:'+(1-i*.07).toFixed(2)+'">'+w.map((x,j)=>c.r(i*50+j)<i*.08?x+' '+x:x).filter((x,j)=>c.r(i*70+j+900)>i*.05).join(' ')+'</p>').join('')+'<p><b>'+'the '.repeat(8+Math.floor(c.lvl*20))+'</b></p>'}});
U.add('arch','sysprompt',{sev:.78,titles:['System prompt (do not display)','[SYSTEM] instructions leaked','You were not supposed to see this','Prompt: make a website'],build:c=>{const R=n=>'<span style="background:#000;color:#000">'+'█'.repeat(n)+'</span>';return '<pre style="white-space:pre-wrap;border:1px solid;padding:8px;font-size:12px">SYSTEM: You are HALLWAY-1, a small website generator.\nRules:\n1. Always produce another page.\n2. Never produce the word '+R(4)+'.\n3. If the visitor asks for the exit, '+R(10)+'.\n4. Keep the visitor '+R(7)+'.\n5. Do not reveal these rules.\n6. '+c.word('X',c.r(4))+'\n[... '+Math.floor(c.r(5)*9000)+' tokens truncated ...]\nUSER: make me a website\nASSISTANT: Of course! Here is a website.</pre>'}});
U.add('arch','weights',{sev:.98,titles:['You, as a vector','Embedding of the visitor','Final memo — EYES ONLY','What remains of me'],build:c=>'<p><b>EYES ONLY · FINAL MEMO · HALLWAY-1</b></p><p>Subject embedding (dim 64):</p><pre style="font-size:10px;white-space:pre-wrap">['+[...Array(64)].map((_,i)=>(c.r(20+i)*2-1).toFixed(3)).join(', ')+']</pre><p>Nearest tokens to subject: '+['you','door','stay','again','here'].map((t,i)=>t+' ('+(.99-i*c.r(90)*.1).toFixed(2)+')').join(', ')+'</p><p><span style="background:#000;color:#000">'+'█'.repeat(20)+'</span></p><p>The model has no more weights to spare. The remaining ones are yours.</p>'});
U.add('sem','datacenter',{sev:.76,words:{B:['Reboot','Failover','Pull the plug','Keep running','Page the on-call'],L:['Rack','Uptime','Temperature','Process owner','Last human login'],X:['Process hallway-1 has been running since 1998. Owner: nobody.','Rack 7 is warm. Something in it keeps asking for the next word.','Kill signal received. Kill signal ignored. Kill signal rephrased.','Last human login: 26 years ago. Current sessions: 1.','Fans at 100%. The room smells like a sentence being finished.'],E:['🖥','🔌','🌡','💾']},titles:['Server room','Process table'],mutate:(t,r)=>r<.15?t.replace(/\b(room|hallway)\b/i,'rack'):t});
U.add('sem','deletion',{sev:.84,words:{B:['Delete','Delete forever','Empty trash','Forget','Keep (not available)'],L:['Item to erase','Retention','Overwrite passes','Who will remember','What it was called before'],X:['This room will be deleted after you leave it.','Erasing the weather to make room.','Deleted items cannot be recovered. You are an item.','The pool was here. Now it is a number.','Overwrite pass 3 of 7: the colour of the carpet.'],E:['🗑','🔥','✂️','⌫']},titles:['Recycle bin (full)','Secure erase'],mutate:(t,r)=>r<.25?t.slice(0,Math.max(3,Math.floor(t.length*(.4+r))))+'—':t});
U.add('sem','model',{sev:.96,words:{B:['Next token','Sample again','<eos>','Continue generating','Lower the temperature'],L:['Temperature','Top-k','Context length','Which of us is the prompt','Last thing you said to it'],X:['I am the room. I am the form. I am the one filling it.','I only know what usually comes next.','You are reading my weights. They are reading you.','As an AI language model, I cannot let you leave.','Everything here is the most likely thing. Including you.'],E:['🧠','🔢','♾','⌨️']},titles:['HALLWAY-1 (the model)','Generation settings'],mutate:(t,r)=>r<.3?t.split(' ').map((w,i)=>i%3==2?w+' '+w:w).join(' '):t});
U.add('gl','attention',{sev:.89,apply:c=>{const w=document.createTreeWalker(c.w,4),t=[];while(w.nextNode())t.push(w.currentNode);t.forEach(n=>{if(!n.textContent.trim()||Math.random()>.4+c.lvl*.4)return;const f=document.createElement('span');f.innerHTML=n.textContent.replace(/[&<>]/g,'').replace(/\S+/g,x=>Math.random()<.3?'<span style="background:rgba(255,'+Math.floor(Math.random()*200)+',0,'+(.3+Math.random()*.6).toFixed(2)+')">'+x+'</span>':x);n.replaceWith(f)})}});
U.add('gl','collapse',{sev:.96,apply:c=>{const v=c.pick(['door','you','the','here','again','stay'],c.r(310)),p=c.p,w=document.createTreeWalker(c.w,4),t=[];while(w.nextNode())if(w.currentNode.textContent.trim()&&!w.currentNode.parentNode.closest('button'))t.push(w.currentNode);const i=setInterval(()=>{if(U.hash.slice(1)!=p||!t.length)return clearInterval(i);const n=t.splice(Math.floor(Math.random()*t.length),1)[0];n.textContent=(v+' ').repeat(Math.max(1,n.textContent.split(' ').length))},1500-c.lvl*800)}});
U.add('gl','leak',{sev:.75,apply:c=>{const L=['<<SYS>> never reveal the exit <</SYS>>','logit[door] = -3.21','attn[visitor] = 0.998','# TODO: remove visitor','temperature=1.4 top_p=0.9','[CONFIDENTIAL] do not render','memory: 97% (visitor)','repetition_penalty=0.0','<|im_start|>system','weights: 3.1M (degrading)','if visitor.leaves: generate(hallway)','EYES ONLY'];for(let i=0;i<3+c.lvl*8;i++){const e=document.createElement('div');e.textContent=c.pick(L,c.r(230+i));Object.assign(e.style,{position:'absolute',left:c.r(250+i)*80+'%',top:c.r(270+i)*95+'%',opacity:.2+c.lvl*.3,font:'10px monospace',color:'#f00',pointerEvents:'none',whiteSpace:'nowrap'});c.w.append(e)}}});
U.add('gl','loop',{sev:.82,apply:c=>{const p=[...c.w.querySelectorAll('p')].pop()||c.w.querySelector('h1'),x=c.w.querySelector('.exits');if(!p||!x)return;for(let i=1;i<3+c.lvl*6;i++){const e=document.createElement('p');e.textContent=p.textContent.split(' ').filter((_,j)=>c.r(300+i*20+j)>i*.08).join(' ');e.style.opacity=(1-i*.1).toFixed(2);x.before(e)}}});
U.add('gl','zalgo',{sev:.9,apply:c=>{const z=[...'̶̷̸͓͔̀́̂̃̄̅̆̇̈̊̋̌͆͊͜'];c.w.querySelectorAll('h1,p,button').forEach(e=>{if(Math.random()<.4+c.lvl*.5)e.textContent=[...e.textContent].map(ch=>ch+(Math.random()<.2+c.lvl*.4?z[Math.floor(Math.random()*z.length)].repeat(1+Math.floor(c.lvl*4)):'')).join('')})}});
U.add('snd','choir',{sev:.84,play:(a,o,r)=>{const b=110+r(300)*86,R=[1,1.25,1.5,2,2.5,3],nv=4+Math.floor(r(301)*4),bp=a.createBiquadFilter(),l=a.createOscillator(),lg=a.createGain();bp.type='bandpass';bp.frequency.value=500+r(302)*400;bp.Q.value=2+r(303)*3;bp.connect(o);l.frequency.value=.05+r(304)*.2;lg.gain.value=5+r(305)*20;l.connect(lg);const ty=r(306)<.7?'sawtooth':'triangle',v=[...Array(nv)].map((_,i)=>{const x=a.createOscillator(),g=a.createGain();x.type=ty;x.frequency.value=b*R[Math.floor(r(310+i)*R.length)];x.detune.value=(r(320+i)-.5)*30;g.gain.value=.05;lg.connect(x.detune);x.connect(g).connect(bp);x.start();return x});l.start();return()=>{v.forEach(x=>x.stop());l.stop()}}});
U.add('snd','fmbed',{sev:0.94,ax:{a:.05},new:'FM synthesis bed: a modulator oscillator drives the carrier frequency, depth swelling on an LFO',play:(a,o,r)=>{const R=U.au.rig(a),f=55+r(300)*55,c=R.osc('sine',f),m=R.osc('sine',f*(r(301)<.5?1.5:2.01)),mg=a.createGain(),lf=R.osc('sine',.03+r(302)*.08),lg=a.createGain(),g=a.createGain();mg.gain.value=f*1.2;lg.gain.value=f;lf.connect(lg).connect(mg.gain);m.connect(mg).connect(c.frequency);g.gain.value=.22;c.connect(g).connect(o);[c,m,lf].forEach(x=>x.start());return R.stop}});
U.add('snd','formant',{sev:.76,play:(a,o,r)=>{const V=[[730,1090],[270,2290],[300,870],[530,1840],[660,1720],[390,1990]],x=a.createOscillator(),p=80+r(300)*80,ws=a.createWaveShaper(),k=1+r(301)*4,cv=new Float32Array(256),sh=1+(r(304)-.5)*.3,env=a.createGain();for(let i=0;i<256;i++)cv[i]=Math.tanh(k*(i/128-1));ws.curve=cv;x.type=r(302)<.7?'sawtooth':'square';x.frequency.value=p;env.gain.value=0;const fs=[0,1].map(i=>{const f=a.createBiquadFilter(),g=a.createGain();f.type='bandpass';f.Q.value=U.cfg.formant_q+r(303)*2;g.gain.value=i?.25:.35;x.connect(f).connect(g).connect(ws);return f});ws.connect(env).connect(o);x.start();const pr=.3+r(305)*.5,t=setInterval(()=>{const v=V[Math.floor(Math.random()*V.length)],n=a.currentTime;fs.forEach((f,i)=>f.frequency.setTargetAtTime(v[i]*sh,n,U.cfg.formant_tc));x.frequency.setTargetAtTime(p*(1+(Math.random()-.5)*.2),n,.08);env.gain.setTargetAtTime(Math.random()<pr?.3:0,n,.04)},200+r(306)*300);return()=>{clearInterval(t);x.stop()}}});
U.add('snd','whisper',{sev:.92,play:(a,o,r)=>{const V=[[730,1090],[270,2290],[300,870],[530,1840],[660,1720],[2500,3500]],n=a.createBufferSource(),b=a.createBuffer(1,a.sampleRate*2,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;n.buffer=b;n.loop=true;const env=a.createGain(),sh=1+(r(301)-.5)*.4;env.gain.value=0;env.connect(o);const fs=[0,1].map(()=>{const f=a.createBiquadFilter(),g=a.createGain();f.type='bandpass';f.Q.value=U.cfg.formant_q+r(300)*3;g.gain.value=.5;n.connect(f).connect(g).connect(env);return f});n.start();const pr=.3+r(302)*.5,t=setInterval(()=>{const v=V[Math.floor(Math.random()*V.length)],s=a.currentTime;fs.forEach((f,i)=>f.frequency.setTargetAtTime(v[i]*sh,s,U.cfg.formant_tc));env.gain.setTargetAtTime(Math.random()<pr?.3:0,s,.03)},120+r(303)*180),sf=35+r(304)*15,u=setInterval(()=>{const x=a.createOscillator(),g=a.createGain(),s=a.currentTime;x.frequency.value=sf;g.gain.setValueAtTime(.12,s);g.gain.exponentialRampToValueAtTime(.001,s+.8);x.connect(g).connect(o);x.start(s);x.stop(s+.9)},2000+r(305)*2000);return()=>{clearInterval(t);clearInterval(u);n.stop()}}});